INSERT INTO "public"."legacy_records" ("id", "organization_id", "title", "category", "suggested_module", "lifecycle", "source_status", "payload", "created_by", "created_at", "updated_at", "deleted_at", "converted_target_table", "converted_target_id", "converted_at") VALUES
	('bffd7df0-5256-4994-ac6c-3c16d88d7fab', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Jaarlijkse Algemene Vergadering (AV)', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905050734", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-06-30", "Opmerking": "VZW-wet verplicht jaarlijkse AV binnen 6 maanden na afsluiting boekjaar. Boekjaar = kalenderjaar → deadline 30 juni. Agenda opstellen, leden uitnodigen, jaarverslag en jaarrekening goedkeuren, eventueel bestuursmandaten hernieuwen.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Algemene Vergadering", "Google Calendar event": "", "Herinnering sturen op": "2026-05-15", "Instantie / organisatie": "Intern (conform statuten BESC)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905050734", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:26:20+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', 'd19d267c-dd42-400b-a6a7-ba385c7661d8', '2026-07-22 11:53:43.234142+00'),
	('1e407b9c-01b8-4284-b3f9-c4331d2117b2', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Jaarverslag opstellen en goedkeuren', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905093208", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-06-15", "Opmerking": "Bestaat uit 2 delen: (1) activiteitenverslag van het voorbije jaar en (2) financieel verslag / jaarrekening. Moet worden goedgekeurd door de AV. Klaar hebben vóór de uitnodiging voor de AV verstuurd wordt.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Jaarverslag", "Google Calendar event": "", "Herinnering sturen op": "2026-05-01", "Instantie / organisatie": "Intern — goedkeuring op AV"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905093208", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:26:23+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '51b32eb9-20a6-4e28-b573-d2cd90d595e4', '2026-07-22 11:53:43.234142+00'),
	('424e4d36-6460-4e32-a295-5a0058c1f4cf', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Notulen AV neerleggen bij KBO', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905109979", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-07-30", "Opmerking": "Verplicht binnen 30 dagen na de AV. Indienen via e-Depot (www.ejustice.just.fgov.be) of via notaris. Kost: gratis via e-Depot voor VZW''s. Notulen moeten ondertekend zijn door minstens 2 bestuurders.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Registratie", "Google Calendar event": "", "Herinnering sturen op": "2026-07-10", "Instantie / organisatie": "KBO — Kruispuntbank van Ondernemingen"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905109979", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:26:27+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '567ab0e6-a440-4041-b45b-b6133e5a0fa3', '2026-07-22 11:53:43.234142+00'),
	('062206a5-db63-4eb7-93ff-f3e0430ce5b4', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Bestuursmandaten up-to-date houden bij KBO', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905084183", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-12-31", "Opmerking": "Bij elke wijziging van bestuurders (aanstelling, ontslag, hernieuwing mandaat) moet dit binnen 30 dagen gepubliceerd worden via e-Depot of notaris in het Belgisch Staatsblad. Jaarlijkse controle of alle mandaten nog actueel zijn aanbevolen.", "Frequentie": "Op aanvraag", "Documentlink": "", "Type verplichting": "Registratie", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "KBO — Kruispuntbank van Ondernemingen"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905084183", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:26:30+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '7abab4d5-475c-4c93-bae6-19adba1de73a', '2026-07-22 11:53:43.234142+00'),
	('25d043ea-ab83-4dce-8e2d-f9c42b79ef79', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Publicatie wijzigingen in Belgisch Staatsblad', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905083433", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "", "Opmerking": "Verplicht bij: wijziging statuten, wijziging bestuurders, wijziging maatschappelijke zetel, fusie of ontbinding. Moet binnen 30 dagen na de beslissing gepubliceerd worden. Gratis via e-Depot voor VZW''s. Let op: statutenwijziging vereist ook notariële akte.", "Frequentie": "Op aanvraag", "Documentlink": "", "Type verplichting": "Publicatie", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "Belgisch Staatsblad — e-Depot (ejustice.just.fgov.be)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905083433", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:26:34+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', 'afaccb65-ad0b-4cf2-8eed-59b75e164e87', '2026-07-22 11:53:43.234142+00'),
	('fd399b84-4030-4fa6-a3ae-9ddb367c5cb2', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Aangifte rechtspersonenbelasting (RPB)', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905024194", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-10-15", "Opmerking": "VZW''s zijn onderworpen aan de rechtspersonenbelasting (niet vennootschapsbelasting). Aangifte via MyMinfin.be. Deadline wordt jaarlijks meegedeeld door FOD Financiën, typisch september-oktober. Kleine VZW''s met weinig belastbare inkomsten vullen een vereenvoudigd formulier in (aangifte 275.1).", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Aangifte", "Google Calendar event": "", "Herinnering sturen op": "2026-09-15", "Instantie / organisatie": "FOD Financiën — MyMinfin.be"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905024194", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:26:46+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '446ee8a7-14ff-4d64-afc8-64d9b082e7b6', '2026-07-22 11:53:43.234142+00'),
	('0905227d-f32d-44ef-818b-34b4af1d1819', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Jaarrekening opstellen', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905109792", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-06-01", "Opmerking": "Kleine VZW (minder dan 1 VTE of minder dan 250.000 EUR gewone ontvangsten): vereenvoudigde jaarrekening, geen neerlegging bij NBB verplicht. Grote VZW: volledige jaarrekening + neerlegging bij NBB. Opstellen met Assist Online, goedkeuren op AV.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Jaarverslag", "Google Calendar event": "", "Herinnering sturen op": "2026-04-15", "Instantie / organisatie": "Intern + Assist Online (accountant)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905109792", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:26:50+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '3d052476-4ecb-424f-9cb0-c2cb35244e5c', '2026-07-22 11:53:43.234142+00'),
	('66c6e2ea-0f32-47ad-88b8-f1e94c5498f2', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Neerlegging jaarrekening bij NBB (grote VZW)', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905109818", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-07-31", "Opmerking": "CONTROLEER EERST: Enkel verplicht voor grote VZW''s (minstens 1 VTE EN meer dan 250.000 EUR gewone ontvangsten OF meer dan 1.000.000 EUR balanstotaal). Neerleggen binnen 30 dagen na goedkeuring op AV. Via NBB Online Filing (www.nbb.be). Kost: €41,80 (klein) of €148,60 (groot schema).", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Publicatie", "Google Calendar event": "", "Herinnering sturen op": "2026-07-10", "Instantie / organisatie": "Nationale Bank van België — NBB (nbb.be)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905109818", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:26:54+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', 'f2e30170-dc6a-4910-a6e8-39a3e587c12f', '2026-07-22 11:53:43.234142+00'),
	('f31c6905-84c9-490e-8e7f-67e4588a4d13', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'BTW-aangifte (indien van toepassing)', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905083681", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "", "Opmerking": "CONTROLEER EERST: VZW''s zijn in principe vrijgesteld van BTW als ze geen economische activiteiten verrichten. Als BESC merchandise verkoopt, advertentie-inkomsten heeft of betalende events organiseert boven bepaalde drempels, kan BTW-plicht van toepassing zijn. Raadpleeg accountant via Assist Online. Kwartaalaangifte = voor 20e van de maand volgend op het kwartaal.", "Frequentie": "Per kwartaal", "Documentlink": "", "Type verplichting": "Aangifte", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "FOD Financiën — MyMinfin.be"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905083681", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:26:58+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '1f918579-52b2-4683-9d48-a19a324056af', '2026-07-22 11:53:43.234142+00'),
	('5adefb1c-6364-4c3f-b022-615992b6d177', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'BA-verzekering VZW hernieuwen', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905093313", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "", "Opmerking": "Burgerlijke Aansprakelijkheidsverzekering voor de VZW en haar bestuurders. Dekt schade aan derden veroorzaakt door de werking van de VZW. VERPLICHT voor elke VZW. Controleer de vervaldatum in je huidige polis en zet die als deadline. Vergelijk jaarlijks tarieven.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Verzekering", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "Verzekeringsmaatschappij (check polis)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905093313", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:27:08+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '29bd8772-c7b9-4607-8705-bdde170db344', '2026-07-22 11:53:43.234142+00'),
	('67ed10b3-759f-42ba-8077-0f1c01ac4a80', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Vrijwilligersverzekering hernieuwen', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905050554", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "", "Opmerking": "WETTELIJK VERPLICHT op basis van de Wet van 3 juli 2005 betreffende de rechten van vrijwilligers. Dekt arbeidsongevallen van vrijwilligers tijdens hun activiteiten voor de VZW. Aanbieders: Vrijwilligerswerk.be heeft goedkope groepspolissen. Lijst van alle vrijwilligers up-to-date houden voor de polis.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Verzekering", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "Verzekeringsmaatschappij (check polis)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905050554", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:27:13+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', 'a0e23d2f-5a67-4010-a4c9-e28d1527432e', '2026-07-22 11:53:43.234142+00'),
	('82745211-e753-48ea-8670-df41b3232d44', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Evenementenverzekering aanvragen (per IRL event)', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905084187", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "", "Opmerking": "Aanvragen minimaal 2 weken vóór elk IRL event. Dekt: lichamelijke letsels van deelnemers, schade aan de locatie, annulatie van het event. Koppel dit item aan het evenementenbord zodat je het niet vergeet bij eventplanning.", "Frequentie": "Op aanvraag", "Documentlink": "", "Type verplichting": "Verzekering", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "Verzekeringsmaatschappij — aanvragen vóór elk IRL event"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905084187", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:27:16+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '2ae3b852-7498-4c6e-a42c-8e3303ffd08d', '2026-07-22 11:53:43.234142+00'),
	('4ad03958-b16f-46d0-8f2b-571893901f62', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Inhoudelijk verslag ontvangen subsidies', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905083723", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "", "Opmerking": "Elke subsidie heeft eigen rapportageverplichtingen — check steeds het subsidiecontract. Typisch: tussentijds verslag na 6 maanden + eindverslag na afloop. Bevat: beschrijving van activiteiten, bereikte doelstellingen, aantal deelnemers. Voeg per subsidie een apart item toe in de groep Subsidies & Dossiers met de rapportagedeadline.", "Frequentie": "Op aanvraag", "Documentlink": "", "Type verplichting": "Rapportage subsidie", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "Subsidiërende instantie (check subsidiecontract)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905083723", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:27:28+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', 'd7b54ade-6d69-47b6-81b9-2996b54127de', '2026-07-22 11:53:43.234142+00'),
	('ca3e1c53-0c55-43d7-99f0-00c2fa3e5e4a', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Financieel verslag ontvangen subsidies', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905084188", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "", "Opmerking": "Financiële verantwoording van de besteding van de subsidie. Vereist: facturen en betalingsbewijzen van alle uitgaven die met de subsidie betaald werden. Bewaar alle bewijsstukken digitaal én fysiek. Originelen bewaren tot minstens 5 jaar na afloop.", "Frequentie": "Op aanvraag", "Documentlink": "", "Type verplichting": "Rapportage subsidie", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "Subsidiërende instantie (check subsidiecontract)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905084188", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:27:31+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '23a413bf-354a-4b26-a22c-263663c65c66', '2026-07-22 11:53:43.234142+00'),
	('295b9412-cd22-4cf9-a807-72867511568e', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'GDPR — Register van verwerkingsactiviteiten bijhouden', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905050714", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-12-31", "Opmerking": "VERPLICHT onder de GDPR (AVG). Intern register bijhouden van alle persoonsgegevens die BESC verwerkt: ledenlijst, nieuwsbriefabonnees, Discord-gebruikers, contactformulier, deelnemers events. Per verwerking: doel, categorieën, bewaartermijn, beveiliging. Sjabloon beschikbaar op website GBA.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Privacy & GDPR", "Google Calendar event": "", "Herinnering sturen op": "2026-11-01", "Instantie / organisatie": "Gegevensbeschermingsautoriteit (GBA) — gegevensbeschermingsautoriteit.be"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905050714", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:27:37+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '72b3bbe4-7cf1-4f6d-8534-956a52f4f6c1', '2026-07-22 11:53:43.234142+00'),
	('9cdb450e-a2bb-43cd-9d28-2f53f006199d', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'GDPR — Privacy policy website controleren', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905083724", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-12-31", "Opmerking": "Jaarlijks controleren of de privacy policy op de website (Google Sites) nog actueel is en alle gegevensverwerkingen correct beschrijft. Bevat verplicht: wie de verwerkingsverantwoordelijke is, welke data verzameld wordt, waarvoor, hoe lang bewaard, hoe rechten uitoefenen. Documentlink toevoegen zodra de URL bekend is.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Privacy & GDPR", "Google Calendar event": "", "Herinnering sturen op": "2026-11-01", "Instantie / organisatie": "Gegevensbeschermingsautoriteit (GBA)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905083724", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:27:41+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '0d33d536-c99d-4bf7-8c87-255581c8956d', '2026-07-22 11:53:43.234142+00'),
	('e14e5885-baea-4c63-8e95-50ea37c0effb', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'GDPR — Cookie consent website controleren', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905016906", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-12-31", "Opmerking": "Google Analytics vereist geldige cookie consent. Controleer of de cookiebanner correct werkt en geen analytics laadt vóór toestemming. GBA verplicht een ''weiger''-optie even prominent als ''aanvaard''. Gebruik bij voorkeur een gecertifieerde Consent Management Platform (CMP).", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Privacy & GDPR", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "Gegevensbeschermingsautoriteit (GBA)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905016906", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:27:44+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '40601f0c-d69b-4127-aeb4-d81607f251da', '2026-07-22 11:53:43.234142+00'),
	('0b64df3b-6557-428b-8c3e-02789f162f1c', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Vrijwilligersovereenkomsten up-to-date', 'Overige', 'Administratie & financiën', 'completed', 'Nieuw', '{"item_id": "2905093260", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-12-31", "Opmerking": "Elke vrijwilliger moet een schriftelijke vrijwilligersovereenkomst hebben. Verplicht te vermelden: naam VZW, naam vrijwilliger, omschrijving activiteiten, eventuele onkostenvergoeding, geheimhoudingsplicht. Ook verplicht: informatienota over de VZW verstrekken vóór start. Jaarlijks controleren of alle actieve vrijwilligers (crew, medewerkers) een geldige overeenkomst hebben.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Contractverplichting", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "Intern — conform Wet vrijwilligerswerk 3 juli 2005"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905093260", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-05-10 21:27:48+00', '2026-07-22 11:53:43.234142+00', NULL, 'tasks', '816e394e-5625-462d-84d0-eeeaad9e6c88', '2026-07-22 11:53:43.234142+00'),
