	('aebfd192-b10f-44f6-b69a-6a008df2ef7e', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'monday', 'BESC HQ', '5096145915', '2905093208', 'tasks', '51b32eb9-20a6-4e28-b573-d2cd90d595e4', 'https://bestreamers.monday.com/boards/5096145915/pulses/2905093208', '{"item_id": "2905093208", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-06-15", "Opmerking": "Bestaat uit 2 delen: (1) activiteitenverslag van het voorbije jaar en (2) financieel verslag / jaarrekening. Moet worden goedgekeurd door de AV. Klaar hebben vóór de uitnodiging voor de AV verstuurd wordt.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Jaarverslag", "Google Calendar event": "", "Herinnering sturen op": "2026-05-01", "Instantie / organisatie": "Intern — goedkeuring op AV"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905093208", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 11:53:43.234142+00', '2026-07-22 11:53:43.234142+00'),
