	('717b530b-96c6-485e-8066-9f80642c30b0', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'monday', 'BESC HQ', '5096145915', '2905083433', 'tasks', 'afaccb65-ad0b-4cf2-8eed-59b75e164e87', 'https://bestreamers.monday.com/boards/5096145915/pulses/2905083433', '{"item_id": "2905083433", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "", "Opmerking": "Verplicht bij: wijziging statuten, wijziging bestuurders, wijziging maatschappelijke zetel, fusie of ontbinding. Moet binnen 30 dagen na de beslissing gepubliceerd worden. Gratis via e-Depot voor VZW''s. Let op: statutenwijziging vereist ook notariële akte.", "Frequentie": "Op aanvraag", "Documentlink": "", "Type verplichting": "Publicatie", "Google Calendar event": "", "Herinnering sturen op": "", "Instantie / organisatie": "Belgisch Staatsblad — e-Depot (ejustice.just.fgov.be)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905083433", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 11:53:43.234142+00', '2026-07-22 11:53:43.234142+00'),
	('19e6c2de-661a-4dee-922c-64cac2329742', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'monday', 'BESC HQ', '1802798573', '1803733986', 'content_items', '720daca8-473c-4c4e-984a-e3ee7dfabf1d', 'https://bestreamers.monday.com/boards/1802798573/pulses/1803733986', '{"item_id": "1803733986", "board_id": "1802798573", "workspace": "BESC HQ", "board_name": "[COMMS] Newsletter planning", "raw_fields": {"Tags": "", "Status": "Nieuw", "Subitems": "", "Verantw.": "Missrinam80", "monday Doc": "", "Link webpage": "", "Verzenddatum": "", "Verzendgroep": "ALGEMEEN"}, "source_url": "https://bestreamers.monday.com/boards/1802798573/pulses/1803733986", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 11:53:43.234142+00', '2026-07-22 11:53:43.234142+00'),
	('8148fc7a-ba04-4b1b-9bfc-1d8f8bce9a37', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'monday', 'BESC HQ', '5096145915', '2905024194', 'tasks', '446ee8a7-14ff-4d64-afc8-64d9b082e7b6', 'https://bestreamers.monday.com/boards/5096145915/pulses/2905024194', '{"item_id": "2905024194", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-10-15", "Opmerking": "VZW''s zijn onderworpen aan de rechtspersonenbelasting (niet vennootschapsbelasting). Aangifte via MyMinfin.be. Deadline wordt jaarlijks meegedeeld door FOD Financiën, typisch september-oktober. Kleine VZW''s met weinig belastbare inkomsten vullen een vereenvoudigd formulier in (aangifte 275.1).", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Aangifte", "Google Calendar event": "", "Herinnering sturen op": "2026-09-15", "Instantie / organisatie": "FOD Financiën — MyMinfin.be"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905024194", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 11:53:43.234142+00', '2026-07-22 11:53:43.234142+00'),
	('23dca97e-3df4-4da4-a514-51173e173dc0', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'monday', 'BESC HQ', '5096145915', '2905109792', 'tasks', '3d052476-4ecb-424f-9cb0-c2cb35244e5c', 'https://bestreamers.monday.com/boards/5096145915/pulses/2905109792', '{"item_id": "2905109792", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-06-01", "Opmerking": "Kleine VZW (minder dan 1 VTE of minder dan 250.000 EUR gewone ontvangsten): vereenvoudigde jaarrekening, geen neerlegging bij NBB verplicht. Grote VZW: volledige jaarrekening + neerlegging bij NBB. Opstellen met Assist Online, goedkeuren op AV.", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Jaarverslag", "Google Calendar event": "", "Herinnering sturen op": "2026-04-15", "Instantie / organisatie": "Intern + Assist Online (accountant)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905109792", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 11:53:43.234142+00', '2026-07-22 11:53:43.234142+00'),
	('a994d88d-7fc3-4d43-a94a-bf3e691e3e51', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'monday', 'BESC HQ', '5096145915', '2905109818', 'tasks', 'f2e30170-dc6a-4910-a6e8-39a3e587c12f', 'https://bestreamers.monday.com/boards/5096145915/pulses/2905109818', '{"item_id": "2905109818", "board_id": "5096145915", "workspace": "BESC HQ", "board_name": "[FIN] Legal & compliance", "raw_fields": {"Owner": "Missrinam80", "Status": "Nieuw", "Deadline": "2026-07-31", "Opmerking": "CONTROLEER EERST: Enkel verplicht voor grote VZW''s (minstens 1 VTE EN meer dan 250.000 EUR gewone ontvangsten OF meer dan 1.000.000 EUR balanstotaal). Neerleggen binnen 30 dagen na goedkeuring op AV. Via NBB Online Filing (www.nbb.be). Kost: €41,80 (klein) of €148,60 (groot schema).", "Frequentie": "Jaarlijks", "Documentlink": "", "Type verplichting": "Publicatie", "Google Calendar event": "", "Herinnering sturen op": "2026-07-10", "Instantie / organisatie": "Nationale Bank van België — NBB (nbb.be)"}, "source_url": "https://bestreamers.monday.com/boards/5096145915/pulses/2905109818", "source_system": "monday"}', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 11:53:43.234142+00', '2026-07-22 11:53:43.234142+00'),
