	('65f6a89b-4d04-4981-8211-17d8b33310ce', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Starter Emote Pack (5 emotes) — Cartoon stijl', 'emote', 'design', NULL, 'Cartoon / Chibi', '{}', '5 basisemotes: blij, lachen, huilen, kwaad, hype. Formaten: 28x28, 56x56, 112x112px PNG transparant. Geschikt voor Twitch, YouTube en Discord. Flagship product.', NULL, NULL, 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 12:03:21.420321+00', '2026-07-22 12:03:21.420321+00', NULL, 'stream_graphics', NULL, NULL, NULL, NULL),
	('e3142408-a3cd-4ce1-bdca-5d7bb52a9e3d', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Minimalist Stream Overlay Pack', 'overlay', 'idea', NULL, 'Minimalistisch', '{}', 'Webcam frame, Starting Soon, BRB, End screen. 1920x1080 PNG. Kleur aanpasbaar in Canva. Strakke look voor professionele streams.', NULL, NULL, 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 12:03:21.420321+00', '2026-07-22 12:03:21.420321+00', NULL, 'stream_graphics', NULL, NULL, NULL, NULL),
	('891c1f68-ff94-4ae2-8d4f-19f39fec227c', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Alert Pack (follow / sub / donate / raid)', 'alert', 'idea', NULL, 'Cartoon / Chibi', '{}', '4 geanimeerde alerts in GIF/WEBM. Compatibel met Streamlabs en StreamElements. Bundel met emote pack voor korting.', NULL, NULL, 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 12:03:21.420321+00', '2026-07-22 12:03:21.420321+00', NULL, 'stream_graphics', NULL, NULL, NULL, NULL),
	('84d1f385-5f22-4ae9-8d2f-01d1c3b7c198', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', 'Twitch Panel Set (8 stuks)', 'panel', 'idea', NULL, 'Minimalistisch', '{}', '8 panels: About, Schedule, Donate, Discord, Social, Specs, Rules, Merch. 320px breed PNG. Kleur aanpasbaar.', NULL, NULL, 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 12:03:21.420321+00', '2026-07-22 12:03:21.420321+00', NULL, 'stream_graphics', NULL, NULL, NULL, NULL),
	('7fb7fab3-c37f-4c2a-b426-799a146e27f2', '2d589c08-2f81-4a30-ab99-ceca23a5bfda', '💎 BUNDEL: Complete Starter Stream Pack', 'bundle', 'design', NULL, 'Cartoon / Chibi', '{}', 'Alles-in-één bundel: 5 emotes + overlay pack + alert pack + panel set. Waarde €53, bundelpijs €35 (33% korting). Vlaggenschip bundel voor nieuwe streamers.', NULL, NULL, 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', 'bf5d12b2-5e5f-4ccd-8831-0d93c56d0ffb', '2026-07-22 12:03:21.420321+00', '2026-07-22 12:03:21.420321+00', NULL, 'stream_graphics', NULL, NULL, NULL, NULL);
